// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx response: its status and the text the server sent with it. */
export class HttpError extends Error {
  constructor(
    message: string,
    readonly status: number,
    readonly body: string,
  ) {
    super(message);
  }
}

/** The date this screen shows the sheet as of ('' when it shows it as it is now): every read asks for the sheet as
 *  of it (?asOf=), and every change is sent marked with it (X-As-Of), so the server refuses it. Kept in step with
 *  the URL's asOf by features/sheet/asof; read from the URL at start-up so the first reads already carry it. */
let asOf = typeof window === 'undefined' ? '' : new URLSearchParams(window.location.search).get('asOf') ?? '';

export function setRequestAsOf(date: string): void {
  asOf = date;
}

function withAsOf(path: string): string {
  return asOf === '' ? path : `${path}${path.includes('?') ? '&' : '?'}asOf=${encodeURIComponent(asOf)}`;
}

function changeHeaders(): Record<string, string> {
  return asOf === '' ? { 'Content-Type': 'application/json' } : { 'Content-Type': 'application/json', 'X-As-Of': asOf };
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status, await res.text());
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(withAsOf(path));
}

/** A read of the store as it is now, whatever date this screen shows the sheet as of. */
export function getJsonNow<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: changeHeaders(),
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: changeHeaders(),
    body: JSON.stringify(body),
  });
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';

/** A sheet: its id, its today (ISO yyyy-mm-dd) and whether it is archived (every change refused). */
export type Sheet = { id: string; today: string; archived: boolean };

export const sheetKey = (sheetId: string) => ['sheet', sheetId, 'meta'] as const;

export function useSheet(sheetId: string) {
  return useQuery({
    queryKey: sheetKey(sheetId),
    queryFn: () => getJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}`),
  });
}

/** The date this user's screen shows the sheet as of (yyyy-mm-dd; '' when it shows it as it is now). It belongs to
 *  the screen, not the sheet: other users are unaffected. While it is set, everything under the sheet is read as it
import { useQuery } from '@tanstack/react-query';
import { getJsonNow } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheet';
import type { Claim } from '../claims/claims';
import type { Person } from '../people/people';
import { sheetDueTotal, sheetOverdueTotal, sumDue, type Rate } from '../rates/rates';
import { floorOf, lateOf, type Settings } from '../settings/settings';
import { useAsOf, type Sheet } from '../sheet/sheet';

/** One read of a sheet as the store holds it now, or (asOf given, yyyy-mm-dd) as it stood at the end of that day,
 *  whatever date this screen shows its own sheet as of. Keyed under the sheet, so a load of that sheet re-reads it. */
function useNow<T>(sheetId: string, part: string, asOf = '') {
  return useQuery({
    queryKey: ['sheet', sheetId, 'now', part, asOf],
    queryFn: () => getJsonNow<T>(`/api/sheets/${encodeURIComponent(sheetId)}${part === '' ? '' : `/${part}`}`
      + (asOf === '' ? '' : `?asOf=${encodeURIComponent(asOf)}`)),
  });
}

type Figures = { people: number; due: string; overdue: string };

/** Adds the figures of sheets[at] to `sum`, then goes on to the next sheet; past the last, shows the figures added
 *  up. One component per sheet keeps each sheet's reads in hooks of its own. */
function Accumulate({ sheets, at, sum, asOf }: { sheets: string[]; at: number; sum: Figures; asOf: string }) {
  if (at >= sheets.length) return <Shown figures={sum} />;
  return <SheetFigures key={sheets[at]} sheets={sheets} at={at} sum={sum} asOf={asOf} />;
}

/** A sheet's figures as it shows them now (or, asOf given, as it showed them at the end of that day, with that day
 *  as its today): its people (retired ones included), its due-total and its overdue-total (as its header shows
 *  them). */
function SheetFigures({ sheets, at, sum, asOf }: { sheets: string[]; at: number; sum: Figures; asOf: string }) {
  const sheetId = sheets[at];
  const people = useNow<Person[]>(sheetId, 'people', asOf).data ?? [];
  const claims = useNow<Claim[]>(sheetId, 'claims', asOf).data ?? [];
  const rates = useNow<Rate[]>(sheetId, 'rates', asOf).data ?? [];
  const settings = useNow<Settings>(sheetId, 'settings', asOf).data;
  const sheetToday = useNow<Sheet>(sheetId, '', asOf).data?.today ?? '';
  const today = asOf !== '' && sheetToday !== '' ? asOf : sheetToday;
  const floor = floorOf(settings);

